#!/usr/bin/env bash
# Copies the store images generated by test/goldens/store_test.dart and
# branding_test.dart into the fastlane folders, as the stores want them:
# screenshots and the feature graphic as JPEG without alpha, the Play icon
# as a PNG.
set -euo pipefail

cd "$(dirname "$0")/.."

src=test/goldens/goldens/store
play=fastlane/metadata/android/es-ES/images
ios=fastlane/screenshots/es-ES

rm -rf "$play" "$ios"
mkdir -p "$play/phoneScreenshots" "$ios"

jpeg() { sips -s format jpeg -s formatOptions 92 "$1" --out "$2" >/dev/null; }

for shot in "$src"/app_store/*.png; do
  jpeg "$shot" "$ios/$(basename "${shot%.png}").jpg"
done
for shot in "$src"/play/[0-9]*.png; do
  jpeg "$shot" "$play/phoneScreenshots/$(basename "${shot%.png}").jpg"
done
jpeg "$src/play/feature_graphic.png" "$play/featureGraphic.jpg"
cp "$src/play/icon.png" "$play/icon.png"
echo "Store images copied into fastlane/."
